<script>
$(function(){
  // Helper for AJAX Submit
  function submitAjaxForm(formElement, url, successMsg) {
    var formData = new FormData(formElement[0]);
    $.ajax({
      url: url,
      type: 'POST',
      data: formData,
      processData: false,
      contentType: false,
      beforeSend: function(){
        $('.btn').attr('disabled', true);
      },
      success: function(response){
        $('.btn').attr('disabled', false);
        $('.modal').modal('hide');
        // Because backend redirects with set_message currently, it might return HTML if it redirects.
        // Actually, we should just reload the page to get the updated status, since doing full DOM update is hard.
        // Even better, let's just use normal forms but show a loading state!
        window.location.reload();
      },
      error: function(){
        $('.btn').attr('disabled', false);
        window.location.reload();
      }
    });
  }

  // Lengkapi Jadwal
  $('.btn-set-schedule').click(function(){
    var id = $(this).data('id');
    var date = $(this).data('date');
    $('#formScheduleSow').attr('action', BASE_URL + 'administrator/tasks/set_schedule_sow/' + id);
    $('#input_estimated_date').val(date);
    $('#modalScheduleSow').modal('show');
  });

  // Upload Brief per-Task (Staff) — file atau teks, minimal salah satu
  $(document).on('click', '.btn-upload-brief', function(){
    var id = $(this).data('id');
    var title = $(this).data('title') || '';
    var content = $(this).data('content') || '';
    $('#formUploadBrief').attr('action', BASE_URL + 'administrator/tasks/upload_brief/' + id);
    $('#formUploadBrief')[0].reset();
    $('#input_brief_title').val(title);
    $('#input_brief_content').val(content);
    $('#modalUploadBrief').modal('show');
  });

  $('#formUploadBrief').on('submit', function(e){
    var content = $.trim($('#input_brief_content').val() || '');
    var hasFile = $('#input_brief_file').val() !== '';
    if (content === '' && !hasFile) {
      e.preventDefault();
      swal('Belum Lengkap', 'Isi teks brief atau pilih file brief minimal salah satu.', 'warning');
      return false;
    }
  });

  // Review SOW
  $('.btn-review-sow').click(function(){
    var id = $(this).data('id');
    var action = $(this).data('action');
    if(action === 'approve') {
      swal({
          title: "Apakah Anda yakin?",
          text: "Apakah Anda yakin ingin menyetujui Brief ini?",
          type: "warning",
          showCancelButton: true,
          confirmButtonColor: "#00a65a",
          confirmButtonText: "Ya, Setujui!",
          cancelButtonText: "Batal",
          closeOnConfirm: true
        },
        function(isConfirm){
          if (isConfirm) {
            $('<form method="post" action="'+BASE_URL+'administrator/tasks/review_sow/'+id+'"><input type="hidden" name="action" value="approve"><input type="hidden" name="<?=$this->security->get_csrf_token_name();?>" value="<?=$this->security->get_csrf_hash();?>"></form>').appendTo('body').submit();
          }
        });
    } else {
      $('#formRejectSow').attr('action', BASE_URL + 'administrator/tasks/review_sow/' + id);
      $('#modalRejectSow').modal('show');
    }
  });

  // Upload Draft
  $('.btn-upload-draft').click(function(){
    var id = $(this).data('id');
    var url = $(this).data('url');
    $('#formUploadDraft').attr('action', BASE_URL + 'administrator/tasks/upload_draft/' + id);
    $('#input_draft_url').val(url);
    $('#modalUploadDraft').modal('show');
  });

  // Review Draft (approve via modal + checkbox Langsung POSTED)
  $('.btn-review-draft').click(function(){
    var id = $(this).data('id');
    var action = $(this).data('action');
    if(action === 'approve') {
      var draftUrl = $(this).data('draft-url') || '';
      var taskTitle = $(this).data('title') || '';
      var platform = $(this).data('platform') || '';
      $('#formApproveDraft').attr('action', BASE_URL + 'administrator/tasks/approve_and_post/' + id);
      $('#check_direct_posted').prop('checked', false);
      $('#input_direct_live_url').val(draftUrl);
      $('#group_direct_live_url').hide();
      $('#approve_task_title').text(taskTitle ? ('— ' + taskTitle) : '');
      $('#approve_platform').text(platform);
      $('#approve_draft_preview').html(draftUrl ? ('<a href="' + draftUrl + '" target="_blank">' + draftUrl + '</a>') : '<span class="text-muted">Link draft kosong.</span>');
      $('#approve_draft_open').attr('href', draftUrl || '#');
      $('#modalApproveDraft').modal('show');
    } else {
      $('#formRejectDraft').attr('action', BASE_URL + 'administrator/tasks/review_draft/' + id);
      $('#modalRejectDraft').modal('show');
    }
  });

  $('#check_direct_posted').change(function(){
    if ($(this).is(':checked')) {
      $('#group_direct_live_url').show();
    } else {
      $('#group_direct_live_url').hide();
    }
  });

  $('#formApproveDraft').on('submit', function(e){
    if ($('#check_direct_posted').is(':checked') && $.trim($('#input_direct_live_url').val() || '') === '') {
      e.preventDefault();
      swal('Belum Lengkap', 'Centang Langsung POSTED wajib diisi link live-nya.', 'warning');
      return false;
    }
  });

  // Live URL
  $('.btn-live-url').click(function(){
    var id = $(this).data('id');
    var url = $(this).data('url');
    $('#formLiveUrl').attr('action', BASE_URL + 'administrator/tasks/set_live_url/' + id);
    $('#input_live_url').val(url);
    $('#modalLiveUrl').modal('show');
  });

  // Sync Video Metrics via Apify
  $(document).on('click', '.btn-sync-posting', function(){
    var $btn = $(this);
    var taskId = $btn.data('id');
    var originalHtml = $btn.html();

    $btn.prop('disabled', true).html('<i class="fa fa-spinner fa-spin"></i>');

    var postData = { id: taskId };
    var csrfName = '<?= $this->security->get_csrf_token_name(); ?>';
    var csrfHash = '<?= $this->security->get_csrf_hash(); ?>';
    postData[csrfName] = csrfHash;

    $.ajax({
      url: BASE_URL + 'administrator/tasks/sync_posting_metrics/' + taskId,
      type: 'POST',
      dataType: 'json',
      data: postData,
      success: function(res) {
        $btn.prop('disabled', false).html(originalHtml);
        if (res.success) {
          swal({
            title: "Scraping Berhasil!",
            text: res.message,
            type: "success",
            confirmButtonText: "OK"
          }, function() {
            window.location.reload();
          });
        } else {
          swal({
            title: "Gagal Sync",
            text: res.message || "Gagal melakukan scraping video.",
            type: "error",
            confirmButtonText: "Tutup"
          });
        }
      },
      error: function(xhr) {
        $btn.prop('disabled', false).html(originalHtml);
        swal({
          title: "Error",
          text: "Terjadi kesalahan saat menghubungi server Apify.",
          type: "error",
          confirmButtonText: "Tutup"
        });
      }
    });
  });

  // Run Auto Scrape for Day +3 / Day +7
  $(document).on('click', '.btn-run-auto-scrape', function(){
    var $btn = $(this);
    var originalHtml = $btn.html();
    $btn.prop('disabled', true).html('<i class="fa fa-spinner fa-spin"></i> Menjalankan Auto Scrape...');

    var postData = {};
    var csrfName = '<?= $this->security->get_csrf_token_name(); ?>';
    var csrfHash = '<?= $this->security->get_csrf_hash(); ?>';
    postData[csrfName] = csrfHash;

    $.ajax({
      url: BASE_URL + 'administrator/tasks/run_auto_scrape',
      type: 'POST',
      dataType: 'json',
      data: postData,
      success: function(res) {
        $btn.prop('disabled', false).html(originalHtml);
        if (res.success) {
          swal({
            title: "Auto-Scrape Selesai!",
            text: res.message,
            type: "success",
            confirmButtonText: "OK"
          }, function() {
            window.location.reload();
          });
        } else {
          swal({
            title: "Gagal Auto-Scrape",
            text: res.message || "Terjadi kesalahan saat auto-scrape.",
            type: "error",
            confirmButtonText: "Tutup"
          });
        }
      },
      error: function(xhr) {
        $btn.prop('disabled', false).html(originalHtml);
        swal({
          title: "Error",
          text: "Terjadi kesalahan saat menghubungi server.",
          type: "error",
          confirmButtonText: "Tutup"
        });
      }
    });
  });
});
</script>

