<!-- Page script -->
<script>
  $(document).ready(function(){
   
    $('.remove-data').click(function(){

      var url = $(this).attr('data-href');

      swal({
          title: "<?= cclang('are_you_sure'); ?>",
          text: "<?= cclang('data_to_be_deleted_can_not_be_restored'); ?>",
          type: "warning",
          showCancelButton: true,
          confirmButtonColor: "#DD6B55",
          confirmButtonText: "<?= cclang('yes_delete_it'); ?>",
          cancelButtonText: "<?= cclang('no_cancel_plx'); ?>",
          closeOnConfirm: true,
          closeOnCancel: true
        },
        function(isConfirm){
          if (isConfirm) {
            document.location.href = url;            
          }
        });

      return false;
    });


    $('#apply').click(function(){

      var bulk = $('#bulk');
      var serialize_bulk = $('#form_tasks').serialize();

      if (bulk.val() == 'delete') {
         swal({
            title: "<?= cclang('are_you_sure'); ?>",
            text: "<?= cclang('data_to_be_deleted_can_not_be_restored'); ?>",
            type: "warning",
            showCancelButton: true,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: "<?= cclang('yes_delete_it'); ?>",
            cancelButtonText: "<?= cclang('no_cancel_plx'); ?>",
            closeOnConfirm: true,
            closeOnCancel: true
          },
          function(isConfirm){
            if (isConfirm) {
               document.location.href = BASE_URL + '/administrator/tasks/delete?' + serialize_bulk;      
            }
          });

        return false;

      } else if(bulk.val() == '')  {
          swal({
            title: "Upss",
            text: "<?= cclang('please_choose_bulk_action_first'); ?>",
            type: "warning",
            showCancelButton: false,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: "Okay!",
            closeOnConfirm: true,
            closeOnCancel: true
          });

        return false;
      }

      return false;

    });/*end appliy click*/


    //check all
    var checkAll = $('#check_all');
    var checkboxes = $('input.check');

    checkAll.on('ifChecked ifUnchecked', function(event) {   
        if (event.type == 'ifChecked') {
            checkboxes.iCheck('check');
        } else {
            checkboxes.iCheck('uncheck');
        }
    });

    checkboxes.on('ifChanged', function(event){
        if(checkboxes.filter(':checked').length == checkboxes.length) {
            checkAll.prop('checked', 'checked');
        } else {
            checkAll.removeProp('checked');
        }
        checkAll.iCheck('update');
    });

    $(document).on('click', '.btn-lihat-catatan', function(e) {
        e.preventDefault();
        var title = $(this).data('title');
        var note = $(this).data('note');
        $('#modal_lihat_catatan_label').text(title);
        $('#catatan_content').text(note);
        $('#modal_lihat_catatan').modal('show');
    });

    // Instant Client-Side Sorting for CPV & CPE (Zero Page Reload)
    $(document).on('click', '.btn-sort-metric', function(e) {
        e.preventDefault();
        var metric = $(this).data('metric'); // 'cpv' or 'cpe'
        var currentDir = $(this).attr('data-dir') || 'desc';
        var nextDir = (currentDir === 'asc') ? 'desc' : 'asc';
        
        // Reset all sort buttons to default inactive state
        $('.btn-sort-metric').removeAttr('data-dir').css('color', '#52606d');
        $('.btn-sort-metric .sort-icon-holder').html('<i class="fa fa-sort" style="color: #c0c6cc; font-size: 11px;"></i>');
        
        // Set this button active with directional icon
        $(this).attr('data-dir', nextDir).css('color', '#007bff');
        var iconClass = (nextDir === 'asc') ? 'fa-sort-amount-asc' : 'fa-sort-amount-desc';
        $(this).find('.sort-icon-holder').html('<i class="fa ' + iconClass + '" style="color: #007bff; font-size: 12px;"></i>');
        
        // Sort rows in DOM instantly
        var rows = $('#tbody_tasks tr').get();
        rows.sort(function(a, b) {
            var valA = parseFloat($(a).data(metric)) || 0;
            var valB = parseFloat($(b).data(metric)) || 0;
            
            if (nextDir === 'asc') {
                if (valA === 0 && valB > 0) return 1;
                if (valB === 0 && valA > 0) return -1;
                return valA - valB;
            } else {
                if (valA === 0 && valB > 0) return 1;
                if (valB === 0 && valA > 0) return -1;
                return valB - valA;
            }
        });
        
        $.each(rows, function(idx, row) {
            $('#tbody_tasks').append(row);
        });
    });

  }); /*end doc ready*/
</script>